"use client";
import { useState, useEffect, useCallback } from 'react';
import { publicClient, getWalletClient } from '@/lib/client';
import ClaimHandle from '@/components/ClaimHandle';
import ProfileHeader from '@/components/ProfileHeader';
import UserSearch from '@/components/UserSearch';

export default function Home() {
  const [account, setAccount] = useState<string | null>(null);
  const [hasHandle, setHasHandle] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  const checkHandle = useCallback(async (address: string) => {
    try {
      const profile = await publicClient.readContract({
        address: process.env.NEXT_PUBLIC_REGISTRY_ADDR as `0x${string}`,
        abi: [{
          name: 'getProfile',
          type: 'function',
          stateMutability: 'view',
          inputs: [{ name: '_user', type: 'address' }],
          outputs: [{ name: 'username', type: 'string' }, { name: 'metadataCID', type: 'string' }],
        }],
        functionName: 'getProfile',
        args: [address as `0x${string}`],
      });
      setHasHandle(!!profile[0]);
    } catch (e) { setHasHandle(false); }
  }, []);

  useEffect(() => {
    const init = async () => {
      const client = await getWalletClient();
      if (client) {
        const addresses = await client.getAddresses();
        if (addresses.length > 0) {
          setAccount(addresses[0]);
          await checkHandle(addresses[0]);
        }
      }
      setLoading(false);
    };
    init();
  }, [checkHandle]);

  return (
    <main className="min-h-screen bg-black text-white p-6">
      <div className="max-w-xl mx-auto">
        <header className="flex justify-between items-center mb-12">
          <h1 className="text-3xl font-black italic tracking-tighter">HARD FORK</h1>
          <button className="text-[10px] bg-zinc-900 border border-zinc-800 px-4 py-2 rounded-full font-bold text-zinc-500">
            {account ? "CONNECTED" : "DISCONNECTED"}
          </button>
        </header>

        {!account ? (
          <button onClick={async () => {
            const client = await getWalletClient();
            if(client) {
              const [addr] = await client.requestAddresses();
              setAccount(addr);
              checkHandle(addr);
            }
          }} className="w-full py-20 border-2 border-dashed border-zinc-800 rounded-[3rem] text-zinc-500 font-bold hover:border-zinc-600 transition-all">
            Connect Wallet to Enter
          </button>
        ) : (
          <div className="space-y-12">
            {/* Identity Gating */}
            {hasHandle ? <ProfileHeader account={account} /> : <ClaimHandle account={account} onSuccess={() => checkHandle(account)} />}

            {/* Search Engine */}
            <section>
              <div className="flex items-center gap-4 mb-6">
                <p className="text-zinc-600 font-black uppercase text-[10px] tracking-[0.25em]">Find Creators</p>
                <div className="h-[1px] flex-1 bg-zinc-900" />
              </div>
              <UserSearch userAccount={account} />
            </section>
          </div>
        )}
      </div>
    </main>
  );
}